const file="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/44.csv";
const csv=await tools.Read({file_path:file});
if(typeof csv!=="string")throw Error("Expected CSV text");
const rows=csv.trim().split("\n");
const parsed=rows.slice(1).map((line,i)=>{const [truck,at,lat,lon,engine,odo]=line.split(",");return {line:i+2,raw:line,truck,at,lat:Number(lat),lon:Number(lon),engine,odo};});
const inWindow=parsed.filter(r=>r.at>="2026-08-31T17:50:00Z"&&r.at<="2026-08-31T18:10:00Z");
function meters(r){const rad=d=>d*Math.PI/180;const dLat=rad(r.lat-29.6805),dLon=rad(r.lon+97.6475);const a=Math.sin(dLat/2)**2+Math.cos(rad(29.6805))*Math.cos(rad(r.lat))*Math.sin(dLon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
text({source:file,header:rows[0],totalRows:parsed.length,windowRows:inWindow.length,within3000m:inWindow.filter(r=>meters(r)<3000)});
text({truck29:parsed.filter(r=>r.truck==="29").map(r=>({line:r.line,quote:r.raw}))});
text({closestWindowRows:inWindow.sort((a,b)=>meters(a)-meters(b)).slice(0,3).map(r=>({line:r.line,quote:r.raw}))});
text(await tools.Grep({pattern:"Soto|Emilio|drv 30|(^|[[:space:]])29([[:space:]]|$)",path:"/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/swap_log.txt",output_mode:"content"}));
